import { writeFile } from "node:fs/promises";
import type { Preferences } from "./collect-preferences";

export const DEFAULT_BONE_CONTENT = (project: Preferences["project"]): string => {
  switch (project) {
    case "react-ts":
      return `
/* eslint-disable */
/* oxlint-disable */
/* biome-ignore-all lint */
/* @ts-nocheck */

import type { HTMLProps } from "react";

/**
 * Auto-generated by Skullmaster.
 *
 * This is the default fallback skeleton component displayed when a
 * matching skeleton implementation cannot be found in the registry.
 *
 * You may freely customize or replace this component to match the
 * loading experience of your application.
 */
type DefaultBoneProps = HTMLProps<HTMLDivElement>;

export default function DefaultBone(props: DefaultBoneProps) {
  return <div {...props}>loading...</div>;
}
`;
    case "preact-ts":
      return `
/* eslint-disable */
/* oxlint-disable */
/* biome-ignore-all lint */
/* @ts-nocheck */

import type { HTMLAttributes } from "preact";

/**
 * Auto-generated by Skullmaster.
 *
 * This is the default fallback skeleton component displayed when a
 * matching skeleton implementation cannot be found in the registry.
 *
 * You may freely customize or replace this component to match the
 * loading experience of your application.
 */
type DefaultBoneProps = HTMLAttributes<HTMLDivElement>;

export default function DefaultBone(props: DefaultBoneProps) {
  return <div {...props}>loading...</div>;
}
`;
    case "react-js":
    case "preact-js":
      return `
/* eslint-disable */
/* oxlint-disable */
/* biome-ignore-all lint */

export default function DefaultBone(props) {
  return <div {...props}>loading...</div>;
}
`;
  }
};

export default async function defaultBone(target: string, project: Preferences["project"]) {
  await writeFile(target, DEFAULT_BONE_CONTENT(project), "utf8");
}
